.fsx-hero-phone{--navy: #26275B; --navy-deep: #1D1E4A; --blue: #4E98D8; --blue-ink: #2F78BA; --teal: #7CD2D3; --mid: #528FC0; --royal: #2E4DA5; --ink: #221C1B; --body: #3A3650; --muted: #6A6880; --bg: #F8F7F7; --white: #FFFFFF; --line: #E3E2EA; --star: #F4B400; --ph: #FFE45C; --grad: linear-gradient(90deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%); --grad-diag: linear-gradient(120deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%); --font: "Poppins", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif; --font-ui: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif; --content: 1240px; --pad-x: 24px; --shadow-card: 0 18px 40px -18px rgba(38, 39, 91, .28); --shadow-btn: 0 14px 30px -12px rgba(46, 77, 165, .55); --navy: #250762; --navy-deep: #1A0446; --blue: #3299D5; --blue-ink: #1F78B4; --ink: #1C1B22; --body: #2F2E36; --muted: #6B6A72; --tint: #EEF0F9; --aqua: #72CCD8; --royal: #174FA2; --grey: #D9D8D7; --teal: #72CCD8; --mid: #3299D5; --grad: linear-gradient(90deg, #72CCD8 0%, #174FA2 100%); --grad-diag: linear-gradient(120deg, #72CCD8 0%, #174FA2 100%); --grad-text: linear-gradient(90deg, #72CCD8 0%, #3299D5 45%, #174FA2 100%); --grad-primary: linear-gradient(135deg, #2B0A80 0%, #250762 55%, #200556 100%); --grad-icon: linear-gradient(135deg, #3299D5 0%, #250762 100%); --shadow-btn: 0 14px 30px -12px rgba(37, 7, 98, .55); font-family:Poppins, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif;font-size:18px;line-height:28.8px;color:rgb(28, 27, 34); display:block;} .fsx-hero-phone *, .fsx-hero-phone *::before, .fsx-hero-phone *::after{box-sizing:border-box;}
.fsx-hero-phone button{background:none;border:0;padding:0;margin:0;font:inherit;color:inherit;border-radius:0;text-transform:none;letter-spacing:inherit;box-shadow:none;cursor:pointer;}
.fsx-hero-phone button:hover, .fsx-hero-phone button:focus{background:none;color:inherit;}
.fsx-hero-phone a{color:inherit;text-decoration:none;background:none;} .fsx-hero-phone a:hover{color:inherit;}
.fsx-hero-phone h1, .fsx-hero-phone h2, .fsx-hero-phone h3, .fsx-hero-phone h4, .fsx-hero-phone p, .fsx-hero-phone ul, .fsx-hero-phone ol, .fsx-hero-phone figure{margin:0;padding:0;} .fsx-hero-phone ul, .fsx-hero-phone ol{list-style:none;}
.fsx-hero-phone img, .fsx-hero-phone svg{display:block;max-width:100%;height:auto;}
.fsx-hero-phone { --navy: #26275B;
  --navy-deep: #1D1E4A;
  --blue: #4E98D8;
  --blue-ink: #2F78BA;   
  --teal: #7CD2D3;
  --mid: #528FC0;
  --royal: #2E4DA5;
  --ink: #221C1B;
  --body: #3A3650;
  --muted: #6A6880;
  --bg: #F8F7F7;
  --white: #FFFFFF;
  --line: #E3E2EA;
  --star: #F4B400;
  --ph: #FFE45C;

  --grad: linear-gradient(90deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%);
  --grad-diag: linear-gradient(120deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%);

  --font: "Poppins", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif;
  --font-ui: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif;

  --content: 1240px;
  --pad-x: 24px;
  --shadow-card: 0 18px 40px -18px rgba(38, 39, 91, .28);
  --shadow-btn: 0 14px 30px -12px rgba(46, 77, 165, .55); }
.fsx-hero-phone *, .fsx-hero-phone *::before, .fsx-hero-phone *::after { box-sizing: border-box; }
.fsx-hero-phone { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
.fsx-hero-phone { margin: 0; font-family: var(--font); font-size: 18px; line-height: 1.6; color: var(--ink); background: var(--bg); -webkit-font-smoothing: antialiased; }
.fsx-hero-phone svg { display: block; max-width: 100%; }
.fsx-hero-phone p { margin: 0 0 1em; }
.fsx-hero-phone p:last-child { margin-bottom: 0; }
.fsx-hero-phone .icon { width: 24px; height: 24px; flex: none; }
.fsx-hero-phone .fsx-con { width: 100%; max-width: calc(var(--content) + var(--pad-x) * 2); margin-inline: auto; padding-inline: var(--pad-x); }
.fsx-hero-phone .bg-geo { background: var(--bg) url("https://cdn.jsdelivr.net/gh/chrismitchell-cmd/first-search-marketing@4d59b7976a0bacac8601ce9d2eba36ebb43a7779/elementor/upload/first-search/design/bg-geometric.jpg") center / cover no-repeat; }
.fsx-hero-phone .gcard { --bw: 8px; --r: 40px; padding: var(--bw); border-radius: var(--r); background: var(--grad-diag); box-shadow: var(--shadow-card); }
.fsx-hero-phone .gcard__in { height: 100%; background: var(--white); border-radius: calc(var(--r) - var(--bw)); }
.fsx-hero-phone .hero { padding-block: clamp(64px, 8vw, 120px) clamp(72px, 9vw, 140px); }
.fsx-hero-phone .hero-grid { display: grid; grid-template-columns: minmax(0, 1fr) 500px; gap: clamp(32px, 6vw, 96px); align-items: center; }
.fsx-hero-phone h1 { font-weight: 700; font-size: clamp(44px, 5.4vw, 80px); line-height: 1.0; letter-spacing: -0.025em; margin-bottom: 26px; }
.fsx-hero-phone h1 span { color: var(--blue); }
.fsx-hero-phone .scn-tabs { display: flex; gap: 6px; margin: -14px 0 16px; padding: 4px; border-radius: 999px; background: #F1F0F6; font-family: var(--font-ui); }
.fsx-hero-phone .scn-tabs span { flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 7px 4px; border-radius: 999px; font-size: 13px; font-weight: 600; color: var(--muted); cursor: pointer; transition: background .25s ease, color .25s ease; }
.fsx-hero-phone .scn-tabs .icon { width: 15px; height: 15px; }
.fsx-hero-phone .scn-tabs span.on { background: var(--white); color: var(--navy); box-shadow: 0 4px 12px -6px rgba(37, 7, 98, .45); }
.fsx-hero-phone .scn { display: none; font-family: var(--font-ui); }
.fsx-hero-phone .scn.is-on { display: block; animation: scnIn .45s ease; }
.fsx-hero-phone .pav { width: 38px; height: 38px; flex: none; border-radius: 50%; display: grid; place-items: center; background: var(--grad-diag); color: #fff; font-size: 13px; font-weight: 700; }
.fsx-hero-phone .ig { position: relative; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; color: #000; }
.fsx-hero-phone .ig-top { display: flex; align-items: center; justify-content: space-between; padding: 0 4px 8px; }
.fsx-hero-phone .ig-logo { font-family: "Grand Hotel", "Brush Script MT", "Segoe Script", cursive; font-size: 29px; line-height: 1; }
.fsx-hero-phone .ig-tico { display: flex; gap: 14px; }
.fsx-hero-phone .igi { width: 22px; height: 22px; color: #000; display: block; }
.fsx-hero-phone .ig-stories { display: flex; gap: 10px; padding: 4px 4px 10px; border-bottom: 1px solid #EFEFEF; overflow: hidden; }
.fsx-hero-phone .ig-st { display: grid; justify-items: center; gap: 4px; flex: none; width: 58px; }
.fsx-hero-phone .ig-st i { width: 54px; height: 54px; border-radius: 50%; padding: 2.5px; background: conic-gradient(from 210deg, #FEDA75, #FA7E1E, #D62976, #962FBF, #4F5BD5, #FEDA75); display: grid; }
.fsx-hero-phone .ig-st i b { border-radius: 50%; border: 2.5px solid #fff; display: grid; place-items: center; background: linear-gradient(135deg, #C7D3E8, #9AA9C7); color: #fff; font-size: 15px; font-weight: 700; }
.fsx-hero-phone .ig-st.you i b { background: var(--grad-diag); }
.fsx-hero-phone .ig-st small { font-size: 11px; color: #262626; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 58px; }
.fsx-hero-phone .ig-view { position: relative; height: 446px; overflow: hidden; }
.fsx-hero-phone .ig-track { transition: transform .8s cubic-bezier(.4, 0, .2, 1); }
.fsx-hero-phone .ig-post { padding-top: 10px; }
.fsx-hero-phone .ig-ph { display: flex; align-items: center; gap: 10px; padding: 0 4px 8px; }
.fsx-hero-phone .ig-ph > div { flex: 1; min-width: 0; display: grid; line-height: 1.2; }
.fsx-hero-phone .ig-ph b { font-size: 13.5px; font-weight: 600; }
.fsx-hero-phone .ig-ph small { font-size: 11.5px; color: #737373; }
.fsx-hero-phone .ig-av { width: 34px; height: 34px; flex: none; border-radius: 50%; padding: 2px; background: conic-gradient(from 210deg, #FEDA75, #FA7E1E, #D62976, #962FBF, #4F5BD5, #FEDA75); display: grid; }
.fsx-hero-phone .ig-av b { border-radius: 50%; border: 2px solid #fff; display: grid; place-items: center; background: var(--grad-diag); color: #fff; font-size: 10.5px; font-weight: 700; }
.fsx-hero-phone .ig-av.sm { width: 28px; height: 28px; }
.fsx-hero-phone .ig-fol { font-size: 13px; font-weight: 600; color: #0095F6; }
.fsx-hero-phone .ig-fol.on { color: #262626; }
.fsx-hero-phone .ig-dots { font-size: 11px; letter-spacing: 1px; color: #262626; }
.fsx-hero-phone .ig-img { display: grid; align-content: end; height: 230px; padding: 16px; color: #fff; background: radial-gradient(220px 160px at 80% 15%, rgba(114, 204, 216, .9), transparent 70%), linear-gradient(140deg, #3299D5, #250762); }
.fsx-hero-phone .ig-img span { font-family: var(--font); font-weight: 700; font-size: 24px; line-height: 1.1; }
.fsx-hero-phone .ig-img small { font-size: 12.5px; opacity: .9; }
.fsx-hero-phone .ig-img--ad { height: 200px; background: radial-gradient(200px 150px at 15% 85%, rgba(114, 204, 216, .8), transparent 70%), linear-gradient(140deg, #250762, #174FA2); }
.fsx-hero-phone .ig-cta { display: flex; justify-content: space-between; align-items: center; padding: 10px 12px; background: #0095F6; color: #fff; font-size: 14px; font-weight: 600; }
.fsx-hero-phone .ig-cta.pulse { animation: igpulse .9s ease 2; }
.fsx-hero-phone .ig-act { display: flex; align-items: center; gap: 14px; padding: 10px 4px 6px; }
.fsx-hero-phone .ig-act .igi { width: 24px; height: 24px; }
.fsx-hero-phone .ig-save { margin-left: auto; }
.fsx-hero-phone .ig-like { display: grid; }
.fsx-hero-phone .ig-like > * { grid-area: 1 / 1; }
.fsx-hero-phone .ig-heartfull { opacity: 0; transform: scale(.4); transition: transform .35s cubic-bezier(.3, 1.6, .5, 1), opacity .2s ease; }
.fsx-hero-phone .ig-like.on .ig-heartfull { opacity: 1; transform: none; }
.fsx-hero-phone .ig-send.pop .igi { animation: pop .5s ease; }
.fsx-hero-phone .ig-likes, .fsx-hero-phone .ig-cap, .fsx-hero-phone .ig-meta { margin: 0; padding: 0 4px; font-size: 13px; line-height: 1.4; color: #000; }
.fsx-hero-phone .ig-likes b, .fsx-hero-phone .ig-cap b { font-weight: 600; }
.fsx-hero-phone .ig-cap { margin-top: 3px; }
.fsx-hero-phone .ig-meta { margin-top: 3px; color: #737373; }
.fsx-hero-phone .ig-toasts { position: absolute; left: 6px; right: 6px; bottom: 10px; display: grid; }
.fsx-hero-phone .ig-toast { grid-area: 1 / 1; display: flex; align-items: center; gap: 10px; padding: 9px 12px; border-radius: 14px; background: rgba(38, 38, 38, .94); color: #fff; font-size: 13px; box-shadow: 0 10px 24px -10px rgba(0, 0, 0, .6); opacity: 0; transform: translateY(12px); transition: opacity .3s ease, transform .3s ease; }
.fsx-hero-phone .ig-toast span:not(.ig-av) { flex: 1; }
.fsx-hero-phone .ig-toast .igi { width: 18px; height: 18px; flex: none; }
.fsx-hero-phone .ig-toast .ig-heartfull { opacity: 1; transform: none; }
.fsx-hero-phone .ig-toast.is-in { opacity: 1; transform: none; }
@media (max-width: 767px) { .fsx-hero-phone .ig-view { height: 420px; } }
@media (max-width: 767px) { .fsx-hero-phone .ig-img { height: 190px; } }
@media (max-width: 767px) { .fsx-hero-phone .ig-img--ad { height: 170px; } }
.fsx-hero-phone .scn .lead-in { display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; border-radius: 16px; background: #F1F0F6; margin-bottom: 14px; }
.fsx-hero-phone .scn .lead-in > div { flex: 1; min-width: 0; display: grid; }
.fsx-hero-phone .scn .lead-in small { font-size: 11.5px; font-weight: 600; text-transform: uppercase; letter-spacing: .05em; color: var(--blue-ink); }
.fsx-hero-phone .scn .lead-in b { font-size: 15px; color: var(--navy); }
.fsx-hero-phone .scn .lead-in span { font-size: 13.5px; color: var(--body); }
.fsx-hero-phone .scn .lead-in em { font-style: normal; font-size: 11.5px; color: var(--muted); white-space: nowrap; }
.fsx-hero-phone .flow { position: relative; display: grid; gap: 12px; margin: 0; padding: 0 0 0 4px; list-style: none; }
.fsx-hero-phone .flow::before { content: ""; position: absolute; left: 22px; top: 10px; bottom: 10px; width: 2px; background: repeating-linear-gradient(180deg, #C9D6EE 0 5px, transparent 5px 10px); }
.fsx-hero-phone .scn .fl { position: relative; display: grid; grid-template-columns: 38px minmax(0, 1fr); gap: 12px; padding: 0; border: 0; }
.fsx-hero-phone .scn .fl > i { width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; background: linear-gradient(#fff, #fff) padding-box, var(--grad-diag) border-box; border: 2px solid transparent; color: var(--navy); }
.fsx-hero-phone .scn .fl > i .icon { width: 18px; height: 18px; }
.fsx-hero-phone .scn .fl > div { padding: 10px 12px; border: 1px solid var(--line); border-radius: 14px; background: #fff; }
.fsx-hero-phone .scn .fl small { display: block; font-size: 11.5px; font-weight: 600; text-transform: uppercase; letter-spacing: .05em; color: var(--blue-ink); margin-bottom: 3px; }
.fsx-hero-phone .scn .fl b { font-size: 14px; color: var(--navy); }
.fsx-hero-phone .scn .fl p { margin: 2px 0 0; font-size: 13px; line-height: 1.4; color: var(--body); }
.fsx-hero-phone .bub { display: inline-block; max-width: 92%; padding: 7px 11px !important; border-radius: 14px 14px 14px 4px; background: #F1F0F6; }
.fsx-hero-phone .bub.me { display: block; width: max-content; margin: 6px 0 0 auto !important; border-radius: 14px 14px 4px 14px; background: var(--blue); color: #fff !important; }
.fsx-hero-phone .callst { font-weight: 600; color: var(--blue-ink) !important; }
.fsx-hero-phone .callst.ok { color: #138A5E !important; }
.fsx-hero-phone .scn .booked { display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 14px; padding: 12px; border: 0; border-radius: 14px; background: var(--grad-diag); color: #fff; font-weight: 600; font-size: 14.5px; }
.fsx-hero-phone .scn .booked .icon { width: 18px; height: 18px; }
@media (max-width: 480px) { .fsx-hero-phone .scn-tabs span { font-size: 12px; } }
@media (max-width: 480px) { .fsx-hero-phone .scn-tabs .icon { display: none; } }
.fsx-hero-phone .phone { --bw: 16px; --r: 64px; height: 690px; }
.fsx-hero-phone .phone .gcard__in { padding: 36px 18px 24px; overflow: hidden; }
.fsx-hero-phone .sbar { display: flex; align-items: center; gap: 12px; height: 58px; padding: 0 20px; border: 1.5px solid var(--line); border-radius: 999px; margin-bottom: 18px; font-family: var(--font-ui); }
.fsx-hero-phone .sbar .icon { width: 20px; height: 20px; color: var(--muted); }
.fsx-hero-phone .squery { min-width: 0; white-space: nowrap; overflow: hidden; font-size: 17px; color: var(--ink); }
.fsx-hero-phone .caret { width: 2px; height: 22px; margin-left: -8px; background: var(--blue); animation: blink 1s steps(1) infinite; }
.fsx-hero-phone .results { display: grid; gap: 12px; font-family: var(--font-ui); }
.fsx-hero-phone .results > * { min-width: 0; }
.fsx-hero-phone .res { border: 1px solid var(--line); border-radius: 14px; padding: 14px 16px; opacity: 0; transform: translateY(8px); transition: opacity .35s ease, transform .35s ease; }
.fsx-hero-phone .res.is-in { opacity: 1; transform: none; }
.fsx-hero-phone .res-kind { display: flex; align-items: center; gap: 6px; margin-bottom: 10px; font-size: 13px; font-weight: 500; color: var(--muted); }
.fsx-hero-phone .res-kind .icon { width: 15px; height: 15px; }
.fsx-hero-phone .mp { display: grid; grid-template-columns: 90px minmax(0, 1fr); gap: 12px; align-items: center; }
.fsx-hero-phone .mp svg { width: 90px; height: 90px; border-radius: 10px; }
.fsx-hero-phone .mp > div { min-width: 0; }
.fsx-hero-phone .mp-row { display: flex; align-items: center; gap: 8px; padding: 6px 8px; border-radius: 8px; font-size: 14.5px; color: var(--muted); }
.fsx-hero-phone .mp-row b { flex: 1; min-width: 0; font-weight: 500; color: #46435a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fsx-hero-phone .mp-row .rk { width: 20px; height: 20px; flex: none; border-radius: 50%; display: grid; place-items: center; font-size: 11.5px; font-weight: 600; background: #ECEBF2; }
.fsx-hero-phone .mp-row .st { flex: none; font-size: 12px; letter-spacing: 1px; color: var(--star); }
.fsx-hero-phone .mp-row.you { background: #EAF4FB; box-shadow: inset 3px 0 0 var(--blue); }
.fsx-hero-phone .mp-row.you b { color: var(--navy); font-weight: 600; }
.fsx-hero-phone .mp-row.you .rk { background: var(--royal); color: #fff; }
.fsx-hero-phone .ai { font-size: 15px; line-height: 1.5; color: var(--body); margin-bottom: 10px; }
.fsx-hero-phone .yb { color: var(--blue-ink); font-weight: 600; }
.fsx-hero-phone .src { display: inline-flex; align-items: center; gap: 6px; padding: 4px 11px; border-radius: 999px; background: #EAF4FB; font-size: 13px; font-weight: 600; color: var(--navy); }
.fsx-hero-phone .src::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--blue); }
.fsx-hero-phone .rv { display: grid; grid-template-columns: 36px minmax(0, 1fr); gap: 10px; }
.fsx-hero-phone .av { width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center; background: var(--navy); color: #fff; font-weight: 600; font-size: 14px; }
.fsx-hero-phone .rv .meta { font-size: 13.5px; color: var(--muted); }
.fsx-hero-phone .rv .meta b { color: var(--ink); font-weight: 600; }
.fsx-hero-phone .rv p { margin: 3px 0 0; font-size: 14.5px; line-height: 1.45; color: var(--body); }
.fsx-hero-phone .stars { color: var(--star); letter-spacing: 1.5px; }
@media (max-width: 1024px) { .fsx-hero-phone .hero-grid { grid-template-columns: 1fr; } }
@media (max-width: 1024px) { .fsx-hero-phone .phone { max-width: 500px; width: 100%; margin-inline: auto; } }
@media (max-width: 767px) { .fsx-hero-phone { --pad-x: 16px; } }
@media (max-width: 767px) { .fsx-hero-phone { font-size: 16.5px; } }
@media (max-width: 767px) { .fsx-hero-phone .phone { --bw: 10px; --r: 44px; height: 660px; } }
@media (max-width: 767px) { .fsx-hero-phone .phone .results { min-height: 470px; align-content: start; } }
@media (max-width: 767px) { .fsx-hero-phone .mp-row { font-size: 13.5px; gap: 6px; padding: 5px 6px; } }
@media (max-width: 767px) { .fsx-hero-phone .mp-row .st { font-size: 10.5px; letter-spacing: 0; } }
@media (max-width: 767px) { .fsx-hero-phone .phone .gcard__in { padding: 22px 12px; } }
@media (max-width: 767px) { .fsx-hero-phone .mp { grid-template-columns: 56px minmax(0, 1fr); gap: 8px; } }
@media (max-width: 767px) { .fsx-hero-phone .mp svg { width: 56px; height: 56px; } }
@media (prefers-reduced-motion: reduce) { .fsx-hero-phone { scroll-behavior: auto; } }
@media (prefers-reduced-motion: reduce) { .fsx-hero-phone *, .fsx-hero-phone *::before, .fsx-hero-phone *::after { transition-duration: .01ms !important; animation: none !important; } }
@media (prefers-reduced-motion: reduce) { .fsx-hero-phone .caret { display: none; } }
.fsx-hero-phone { --navy: #250762;            
  --navy-deep: #1A0446;
  --blue: #3299D5;            
  --blue-ink: #1F78B4;        
  --ink: #1C1B22;             
  --body: #2F2E36;
  --muted: #6B6A72;
  --tint: #EEF0F9;            
  --aqua: #72CCD8; --royal: #174FA2; --grey: #D9D8D7; --teal: #72CCD8; --mid: #3299D5;
  --grad: linear-gradient(90deg, #72CCD8 0%, #174FA2 100%);          
  --grad-diag: linear-gradient(120deg, #72CCD8 0%, #174FA2 100%);
  --grad-text: linear-gradient(90deg, #72CCD8 0%, #3299D5 45%, #174FA2 100%);
  --grad-primary: linear-gradient(135deg, #2B0A80 0%, #250762 55%, #200556 100%);
  --grad-icon: linear-gradient(135deg, #3299D5 0%, #250762 100%);
  --shadow-btn: 0 14px 30px -12px rgba(37, 7, 98, .55); }
.fsx-hero-phone h1 span { color: transparent; background: var(--grad-text); -webkit-background-clip: text; background-clip: text;
  -webkit-box-decoration-break: clone; box-decoration-break: clone; }
