/* 1. Hero demo: Search -> Social -> Automation, on a loop (click a tab to jump) */
  const DEMO = [
    { q: 'best dentist near me', c1: 'Seacoast Family Dental', c2: 'Harbor Smiles', ai: 'is the top-rated dentist near you, with hundreds of five-star reviews and new patient openings this week.', who: 'Megan R.', rv: 'Booked a cleaning with <span class="yb">Your Business</span> and got in the same week. Best dental visit I\'ve had.' },
    { q: 'hvac repair near me', c1: 'Granite State Heating', c2: 'North Shore Air', ai: 'is the most-recommended HVAC company in your area, known for same-day service and upfront pricing.', who: 'Dave P.', rv: 'Furnace died on a Sunday. <span class="yb">Your Business</span> had a tech here in two hours. Can\'t recommend them enough.' },
    { q: 'roofer near me', c1: 'Summit Roofing Co.', c2: 'Coastal Roof Pros', ai: 'is a highly rated local roofer with a 10-year workmanship warranty and free inspections.', who: 'Lisa K.', rv: '<span class="yb">Your Business</span> replaced our roof in two days and left the yard cleaner than they found it.' }
  ];
  const sq = $('#sq'), scenes = $$('.scn'), tabs = $$('.scn-tabs span');
  const fill = d => { $('[data-f="c1"]').textContent = d.c1; $('[data-f="c2"]').textContent = d.c2; $('[data-f="ai"]').textContent = d.ai; $('[data-f="who"]').textContent = d.who; $('[data-f="ini"]').textContent = d.who[0]; $('[data-f="rv"]').innerHTML = d.rv; };
  let gen = 0, qi = 0;
  const step = async (g, ms) => { await wait(ms); if (g !== gen) throw 0; };
  const reset = sc => { $$('.res, .note', sc).forEach(c => c.classList.remove('is-in')); };
  const showAll = sc => { $$('.res, .note', sc).forEach(c => c.classList.add('is-in')); };
  const PLAY = [
    async (g, sc) => { // Search + paid/organic results
      const d = DEMO[qi++ % DEMO.length]; fill(d); sq.textContent = '';
      for (let c = 1; c <= d.q.length; c++) { sq.textContent = d.q.slice(0, c); await step(g, 55 + Math.random() * 45); }
      await step(g, 350);
      for (const c of $$('.res', sc)) { c.classList.add('is-in'); await step(g, 420); }
      await step(g, 3800);
    },
    async (g, sc) => { // Social: an Instagram post gets liked, followed and shared, then the feed scrolls to a sponsored post
      const track = $('.ig-track', sc), like = $('[data-c="like"]', sc), likes = $('[data-c="likes"]', sc), fol = $('[data-c="follow"]', sc), send = $('[data-c="send"]', sc), toasts = $$('.ig-toast', sc), cta = $('.ig-cta', sc);
      const toast = i => toasts.forEach((t, k) => t.classList.toggle('is-in', k === i));
      track.style.transform = 'none'; like.classList.remove('on'); likes.textContent = 128; fol.textContent = 'Follow'; fol.classList.remove('on'); toast(-1); cta.classList.remove('pulse');
      await step(g, 700);
      like.classList.add('on'); likes.textContent = 129; toast(0); await step(g, 1300);
      fol.textContent = 'Following'; fol.classList.add('on'); toast(1); await step(g, 1300);
      send.classList.add('pop'); toast(2); await step(g, 900); send.classList.remove('pop');
      for (let n = 130; n <= 141; n++) { likes.textContent = n; await step(g, 90); }
      toast(-1); await step(g, 500);
      track.style.transform = `translateY(-${$('.ig-post', sc).offsetHeight + 4}px)`; await step(g, 1100);
      cta.classList.add('pulse'); toast(3); await step(g, 2600);
    },
    async (g, sc) => { // Automation: email -> text -> call -> booked
      const call = $('[data-c="call"]', sc); call.textContent = 'Ringing…'; call.classList.remove('ok');
      for (const c of $$('.res', sc)) {
        c.classList.add('is-in');
        if (c.contains(call)) { await step(g, 1100); call.classList.add('ok'); for (let t = 0; t <= 4; t++) { call.textContent = `Connected · 00:0${t}`; await step(g, 380); } }
        else await step(g, 900);
      }
      await step(g, 3200);
    }
  ];
  const go = async i => {
    const g = ++gen;
    try {
      for (;;) {
        scenes.forEach((sc, k) => { sc.classList.toggle('is-on', k === i); reset(sc); });
        tabs.forEach((t, k) => t.classList.toggle('on', k === i));
        await PLAY[i](g, scenes[i]);
        i = (i + 1) % scenes.length;
      }
    } catch (e) { if (e !== 0) throw e; }
  };
  tabs.forEach((t, k) => t.addEventListener('click', () => {
    if (RM) { scenes.forEach((sc, n) => sc.classList.toggle('is-on', n === k)); tabs.forEach((x, n) => x.classList.toggle('on', n === k)); return; }
    go(k);
  }));
  if (RM) { fill(DEMO[0]); sq.textContent = DEMO[0].q; scenes.forEach(showAll); $$('.ig-like').forEach(l => l.classList.add('on')); }
  else wait(500).then(() => go(0));
